     1	package br.com.pousadamarealta.reservas.web;
     2	
     3	import br.com.pousadamarealta.reservas.domain.DomainException;
     4	import br.com.pousadamarealta.reservas.domain.ErrorCode;
     5	import br.com.pousadamarealta.reservas.domain.RatePlan;
