     7	import com.fasterxml.jackson.databind.JsonNode;
     8	import com.fasterxml.jackson.databind.ObjectMapper;
     9	
    10	import java.time.LocalDate;
    11	import java.time.YearMonth;
    12	import java.time.format.DateTimeParseException;
    13	
    14	/** Valida e converte as entradas da API; qualquer defeito vira INVALID_REQUEST. */
    15	final class RequestParser {
    16	    private final ObjectMapper mapper;
    17	
    18	    RequestParser(ObjectMapper mapper) {
    19	        this.mapper = mapper;
    20	    }
    21	
    22	    NewReservation newReservation(String body) {
    23	        JsonNode json;
    24	        try {
    25	            json = mapper.readTree(body);
    26	        } catch (Exception e) {
    27	            throw invalid("O corpo da requisição não é um JSON válido");
    28	        }
    29	        if (json == null || !json.isObject()) {
    30	            throw invalid("O corpo da requisição deve ser um objeto JSON");
    31	        }
    32	        int roomNumber = integer(json, "roomNumber");
    33	        String guestName = text(json, "guestName");
    34	        String guestEmail = text(json, "guestEmail");
    35	        String guestCpf = text(json, "guestCpf");
    36	        LocalDate checkIn = date(text(json, "checkIn"), "checkIn");
    37	        LocalDate checkOut = date(text(json, "checkOut"), "checkOut");
    38	        int guests = integer(json, "guests");
    39	        String planName = text(json, "ratePlan");
    40	        if (!checkOut.isAfter(checkIn)) {
    41	            throw invalid("checkOut deve ser depois de checkIn");
    42	        }
    43	        if (guests < 1) {
    44	            throw invalid("guests deve ser pelo menos 1");
    45	        }
    46	        RatePlan plan;
    47	        try {
    48	            plan = RatePlan.valueOf(planName);
    49	        } catch (IllegalArgumentException e) {
    50	            throw invalid("ratePlan deve ser STANDARD ou NON_REFUNDABLE");
    51	        }
    52	        return new NewReservation(roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, plan);
    53	    }
    54	
    55	    LocalDate queryDate(String value, String name) {
    56	        if (value == null) {
    57	            throw invalid("Informe " + name);
    58	        }
    59	        return date(value, name);
    60	    }
    61	
    62	    YearMonth queryMonth(String value, String name) {
    63	        if (value == null) {
    64	            throw invalid("Informe " + name);
    65	        }
    66	        try {
    67	            return YearMonth.parse(value);
    68	        } catch (DateTimeParseException e) {
    69	            throw invalid(name + " deve estar no formato AAAA-MM");
    70	        }
    71	    }
    72	
    73	    private static LocalDate date(String value, String name) {
    74	        try {
    75	            return LocalDate.parse(value);
    76	        } catch (DateTimeParseException e) {
    77	            throw invalid(name + " deve estar no formato AAAA-MM-DD");
    78	        }
    79	    }
    80	
    81	    private static String text(JsonNode json, String field) {
    82	        JsonNode node = json.get(field);
    83	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    84	            throw invalid("Campo obrigatório ausente ou inválido: " + field);
    85	        }
    86	        return node.asText();
    87	    }
    88	
    89	    private static int integer(JsonNode json, String field) {
    90	        JsonNode node = json.get(field);
    91	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    92	            throw invalid("Campo obrigatório ausente ou inválido: " + field);
    93	        }
    94	        return node.intValue();
    95	    }
    96	
    97	    private static DomainException invalid(String message) {
    98	        return new DomainException(ErrorCode.INVALID_REQUEST, message);
    99	    }
   100	}
