    13	
    14	import java.util.Map;
    15	
    16	/** Rotas HTTP da API. */
    17	public class App {
    18	    private static final String JSON = "application/json";
    19	    private static final String CSV = "text/csv; charset=utf-8";
    20	
    21	    private final ReservationService reservations;
    22	    private final ReportService reports;
    23	    private final ObjectMapper mapper = new ObjectMapper()
    24	            .registerModule(new JavaTimeModule())
    25	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
    26	            .enable(JsonGenerator.Feature.WRITE_BIGDECIMAL_AS_PLAIN);
    27	    private final RequestParser parser = new RequestParser(mapper);
    28	
    29	    public App(ReservationService reservations, ReportService reports) {
    30	        this.reservations = reservations;
    31	        this.reports = reports;
    32	    }
    33	
    34	    public Javalin create() {
    35	        Javalin app = Javalin.create(config -> config.showJavalinBanner = false);
    36	
    37	        app.get("/rooms", ctx -> json(ctx, 200, reservations.listRooms()));
    38	        app.post("/reservations", ctx -> json(ctx, 201, reservations.create(parser.newReservation(ctx.body()))));
    39	        app.get("/reservations/{id}", ctx -> json(ctx, 200, reservations.get(id(ctx))));
    40	        app.post("/reservations/{id}/confirmation", ctx -> json(ctx, 200, reservations.confirm(id(ctx))));
    41	        app.post("/reservations/{id}/cancellation", ctx -> json(ctx, 200, reservations.cancel(id(ctx))));
    42	        app.post("/reservations/{id}/check-in", ctx -> json(ctx, 200, reservations.checkIn(id(ctx))));
    43	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, reservations.checkOut(id(ctx))));
    44	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, reservations.receipt(id(ctx))));
    45	        app.get("/messages", ctx -> json(ctx, 200, reservations.listMessages()));
    46	        app.get("/reports/occupancy", ctx -> csv(ctx,
    47	                reports.occupancy(parser.queryDate(ctx.queryParam("date"), "date"))));
    48	        app.get("/reports/revenue", ctx -> csv(ctx,
    49	                reports.revenue(parser.queryMonth(ctx.queryParam("month"), "month"))));
    50	
    51	        app.exception(DomainException.class, (e, ctx) -> error(ctx, e.code(), e.getMessage()));
    52	        app.exception(Exception.class, (e, ctx) -> {
    53	            e.printStackTrace();
    54	            ctx.status(500).contentType(JSON).result(write(Map.of("error", "INTERNAL_ERROR",
    55	                    "message", "Erro interno")));
    56	        });
    57	        app.error(404, ctx -> {
    58	            if (ctx.result() == null || ctx.result().isEmpty()) {
    59	                ctx.contentType(JSON).result(write(Map.of("error", "NOT_FOUND", "message", "Rota não encontrada")));
    60	            }
    61	        });
    62	        return app;
    63	    }
    64	
    65	    private static long id(Context ctx) {
    66	        try {
    67	            return Long.parseLong(ctx.pathParam("id"));
    68	        } catch (NumberFormatException e) {
    69	            throw new DomainException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva não existe");
    70	        }
    71	    }
    72	
    73	    private void json(Context ctx, int status, Object body) {
    74	        ctx.status(status).contentType(JSON).result(write(body));
    75	    }
    76	
    77	    private void csv(Context ctx, String body) {
    78	        ctx.status(200).contentType(CSV).result(body);
    79	    }
    80	
    81	    private void error(Context ctx, ErrorCode code, String message) {
    82	        ctx.status(statusOf(code)).contentType(JSON).result(write(Map.of("error", code.name(), "message", message)));
    83	    }
    84	
    85	    private static int statusOf(ErrorCode code) {
    86	        return switch (code) {
    87	            case INVALID_REQUEST -> 400;
    88	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
    89	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
    90	            case CAPACITY_EXCEEDED -> 422;
    91	        };
    92	    }
    93	
    94	    private String write(Object body) {
    95	        try {
    96	            return mapper.writeValueAsString(body);
    97	        } catch (Exception e) {
    98	            throw new IllegalStateException(e);
    99	        }
   100	    }
   101	}
