    29	
    30	    public String occupancy(LocalDate night) {
    31	        return database.inTransaction(c -> {
    32	            Map<Integer, Room> byNumber = rooms.findAll(c).stream()
    33	                    .collect(Collectors.toMap(Room::number, Function.identity()));
    34	            List<Reservation> occupying = reservations.findPaidOnNight(c, night);
    35	            StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    36	            for (Reservation r : occupying) {
    37	                csv.append(r.roomNumber()).append(',')
    38	                        .append(byNumber.get(r.roomNumber()).type()).append(',')
    39	                        .append(r.id()).append(',')
    40	                        .append(r.checkIn()).append(',')
    41	                        .append(r.checkOut()).append('\n');
    42	            }
    43	            long occupied = occupying.stream().map(Reservation::roomNumber).distinct().count();
    44	            csv.append("total,").append(occupied).append('/').append(byNumber.size()).append('\n');
    45	            return csv.toString();
    46	        });
    47	    }
    48	
    49	    public String revenue(YearMonth month) {
    50	        return database.inTransaction(c -> {
    51	            List<Reservation> list = reservations.findRetainingMoney(c, month.atDay(1), month.plusMonths(1).atDay(1));
    52	            StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    53	            BigDecimal total = Money.ZERO;
    54	            for (Reservation r : list) {
    55	                BigDecimal amount = Money.scale(r.retained());
