    58	                        .append(r.roomNumber()).append(',')
    59	                        .append(r.checkIn()).append(',')
    60	                        .append(r.checkOut()).append(',')
    61	                        .append(r.status()).append(',')
    62	                        .append(amount.toPlainString()).append('\n');
    63	            }
    64	            csv.append("total,").append(total.toPlainString()).append('\n');
    65	            return csv.toString();
    66	        });
    67	    }
