     9	import br.com.pousadamarealta.reservas.notification.Notifier;
    10	import br.com.pousadamarealta.reservas.notification.ReservationEvent;
    11	import br.com.pousadamarealta.reservas.persistence.Database;
    12	import br.com.pousadamarealta.reservas.persistence.MessageRepository;
    13	import br.com.pousadamarealta.reservas.persistence.ReservationRepository;
    14	import br.com.pousadamarealta.reservas.persistence.RoomRepository;
    15	
    16	import java.sql.Connection;
    17	import java.sql.SQLException;
    18	import java.util.List;
    19	
    20	/** Casos de uso das reservas. Cada operação é uma transação, inclusive as mensagens que ela dispara. */
    21	public class ReservationService {
    22	    private final Database database;
    23	    private final RoomRepository rooms;
    24	    private final ReservationRepository reservations;
    25	    private final MessageRepository messages;
    26	    private final List<Notifier> notifiers;
    27	
    28	    public ReservationService(Database database, RoomRepository rooms, ReservationRepository reservations,
    29	                              MessageRepository messages, List<Notifier> notifiers) {
    30	        this.database = database;
    31	        this.rooms = rooms;
    32	        this.reservations = reservations;
    33	        this.messages = messages;
    34	        this.notifiers = List.copyOf(notifiers);
    35	    }
    36	
    37	    public List<Room> listRooms() {
    38	        return database.inTransaction(rooms::findAll);
    39	    }
    40	
    41	    public List<Message> listMessages() {
    42	        return database.inTransaction(messages::findAll);
    43	    }
    44	
    45	    public Reservation create(NewReservation request) {
    46	        return database.inTransaction(c -> {
    47	            Room room = rooms.findForUpdate(c, request.roomNumber()).orElseThrow(
    48	                    () -> new DomainException(ErrorCode.ROOM_NOT_FOUND, "Quarto " + request.roomNumber() + " não existe"));
    49	            Reservation reservation = Reservation.create(room, request.guestName(), request.guestEmail(),
    50	                    request.guestCpf(), request.checkIn(), request.checkOut(), request.guests(), request.ratePlan());
    51	            if (reservations.hasOverlap(c, room.number(), request.checkIn(), request.checkOut())) {
    52	                throw new DomainException(ErrorCode.ROOM_UNAVAILABLE,
    53	                        "O quarto " + room.number() + " já está reservado em alguma das noites pedidas");
    54	            }
    55	            return reservations.insert(c, reservation);
    56	        });
    57	    }
    58	
    59	    public Reservation get(long id) {
    60	        return database.inTransaction(c -> load(c, id, false));
    61	    }
    62	
    63	    public Reservation confirm(long id) {
    64	        return database.inTransaction(c -> {
    65	            Reservation confirmed = load(c, id, true).confirm();
    66	            reservations.updateState(c, confirmed);
    67	            publish(c, new ReservationEvent.Confirmed(confirmed, room(c, confirmed)));
    68	            return confirmed;
    69	        });
    70	    }
    71	
    72	    public Reservation cancel(long id) {
    73	        return database.inTransaction(c -> {
    74	            Reservation before = load(c, id, true);
    75	            Reservation cancelled = before.cancel();
    76	            reservations.updateState(c, cancelled);
    77	            boolean wasConfirmed = before.status().isPaid();
    78	            publish(c, new ReservationEvent.Cancelled(cancelled, room(c, cancelled), wasConfirmed));
    79	            return cancelled;
    80	        });
    81	    }
    82	
    83	    public Reservation checkIn(long id) {
    84	        return database.inTransaction(c -> {
    85	            Reservation checkedIn = load(c, id, true).doCheckIn();
    86	            reservations.updateState(c, checkedIn);
    87	            return checkedIn;
    88	        });
    89	    }
    90	
    91	    public Receipt checkOut(long id) {
    92	        return database.inTransaction(c -> {
    93	            Reservation checkedOut = load(c, id, true).doCheckOut();
    94	            reservations.updateState(c, checkedOut);
    95	            return Receipt.of(checkedOut, room(c, checkedOut));
    96	        });
    97	    }
    98	
    99	    /** Segunda via do comprovante: só existe para reserva paga. */
   100	    public Receipt receipt(long id) {
   101	        return database.inTransaction(c -> {
   102	            Reservation reservation = load(c, id, false);
   103	            if (!reservation.status().isPaid()) {
   104	                throw new DomainException(ErrorCode.OPERATION_NOT_ALLOWED,
   105	                        "Só há comprovante para reserva paga; status atual: " + reservation.status());
   106	            }
   107	            return Receipt.of(reservation, room(c, reservation));
   108	        });
   109	    }
   110	
   111	    private Reservation load(Connection c, long id, boolean forUpdate) throws SQLException {
   112	        var found = forUpdate ? reservations.findForUpdate(c, id) : reservations.find(c, id);
   113	        return found.orElseThrow(
   114	                () -> new DomainException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva " + id + " não existe"));
   115	    }
   116	
   117	    private Room room(Connection c, Reservation reservation) throws SQLException {
   118	        return rooms.find(c, reservation.roomNumber()).orElseThrow(
   119	                () -> new IllegalStateException("Quarto " + reservation.roomNumber() + " desapareceu"));
   120	    }
   121	
   122	    private void publish(Connection c, ReservationEvent event) throws SQLException {
   123	        for (Notifier notifier : notifiers) {
   124	            for (Message message : notifier.messagesFor(event)) {
   125	                messages.insert(c, message);
   126	            }
   127	        }
   128	    }
   129	}

