     5	
     6	import static br.com.pousadamarealta.reservas.domain.ReservationStatus.CANCELLED;
     7	import static br.com.pousadamarealta.reservas.domain.ReservationStatus.CHECKED_IN;
     8	import static br.com.pousadamarealta.reservas.domain.ReservationStatus.CHECKED_OUT;
     9	import static br.com.pousadamarealta.reservas.domain.ReservationStatus.CONFIRMED;
    10	import static br.com.pousadamarealta.reservas.domain.ReservationStatus.PENDING;
    11	
    12	/** Reserva imutável; cada transição devolve uma nova instância. {@code id} é null até ser gravada. */
    13	public record Reservation(
    14	        Long id,
    15	        int roomNumber,
    16	        String guestName,
    17	        String guestEmail,
    18	        String guestCpf,
    19	        LocalDate checkIn,
    20	        LocalDate checkOut,
    21	        int guests,
    22	        RatePlan ratePlan,
    23	        int nights,
    24	        BigDecimal subtotal,
    25	        BigDecimal discount,
    26	        BigDecimal total,
    27	        ReservationStatus status,
    28	        BigDecimal amountPaid,
    29	        BigDecimal refund) {
    30	
    31	    public static Reservation create(Room room, String guestName, String guestEmail, String guestCpf,
    32	                                     LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    33	        if (guests < 1) {
    34	            throw new DomainException(ErrorCode.INVALID_REQUEST, "guests deve ser pelo menos 1");
    35	        }
    36	        if (!checkOut.isAfter(checkIn)) {
    37	            throw new DomainException(ErrorCode.INVALID_REQUEST, "checkOut deve ser depois de checkIn");
    38	        }
    39	        if (guests > room.capacity()) {
    40	            throw new DomainException(ErrorCode.CAPACITY_EXCEEDED,
    41	                    "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    42	        }
    43	        Pricing.Quote quote = Pricing.quote(room, checkIn, checkOut, ratePlan);
    44	        return new Reservation(null, room.number(), guestName, guestEmail, guestCpf, checkIn, checkOut, guests,
    45	                ratePlan, quote.nights(), quote.subtotal(), quote.discount(), quote.total(),
    46	                PENDING, Money.ZERO, null);
    47	    }
    48	
    49	    public Reservation confirm() {
    50	        requireStatus("confirmar", PENDING);
    51	        return copy(CONFIRMED, total, refund);
    52	    }
    53	
    54	    public Reservation doCheckIn() {
    55	        requireStatus("fazer check-in de", CONFIRMED);
    56	        return copy(CHECKED_IN, amountPaid, refund);
    57	    }
    58	
    59	    public Reservation doCheckOut() {
    60	        requireStatus("fazer check-out de", CHECKED_IN);
    61	        return copy(CHECKED_OUT, amountPaid, refund);
    62	    }
    63	
    64	    public Reservation cancel() {
    65	        requireStatus("cancelar", PENDING, CONFIRMED);
    66	        BigDecimal toRefund = status == CONFIRMED && ratePlan.refundable() ? amountPaid : Money.ZERO;
    67	        return copy(CANCELLED, amountPaid, toRefund);
    68	    }
    69	
    70	    /** O que ficou com a pousada: pago menos devolvido. */
    71	    public BigDecimal retained() {
    72	        return refund == null ? amountPaid : amountPaid.subtract(refund);
    73	    }
    74	
    75	    private void requireStatus(String action, ReservationStatus... allowed) {
    76	        for (ReservationStatus s : allowed) {
    77	            if (status == s) {
    78	                return;
    79	            }
    80	        }
    81	        throw new DomainException(ErrorCode.OPERATION_NOT_ALLOWED,
    82	                "Não é possível " + action + " uma reserva com status " + status);
    83	    }
    84	
    85	    private Reservation copy(ReservationStatus newStatus, BigDecimal newPaid, BigDecimal newRefund) {
    86	        return new Reservation(id, roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests,
    87	                ratePlan, nights, subtotal, discount, total, newStatus, newPaid, newRefund);
    88	    }
    89	}
