    14	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    15	    }
    16	
    17	    /** Alta temporada: de 15/12 ao fim de fevereiro, e julho inteiro. */
    18	    public static boolean isHighSeason(LocalDate night) {
    19	        Month month = night.getMonth();
    20	        return month == Month.JANUARY
    21	                || month == Month.FEBRUARY
    22	                || month == Month.JULY
    23	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
    24	    }
    25	
    26	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    27	        BigDecimal rate = room.nightlyRate();
    28	        return Money.scale(isHighSeason(night) ? rate.multiply(HIGH_SEASON_FACTOR) : rate);
    29	    }
    30	
    31	    /** As noites vão de checkIn (inclusive) a checkOut (exclusive). */
    32	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    33	        BigDecimal subtotal = Money.ZERO;
    34	        int nights = 0;
    35	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    36	            subtotal = subtotal.add(nightPrice(room, night));
    37	            nights++;
    38	        }
    39	        BigDecimal discount = Money.scale(subtotal.multiply(plan.discountRate()));
    40	        BigDecimal total = Money.scale(subtotal.subtract(discount));
    41	        return new Quote(nights, subtotal, discount, total);
    42	    }
    43	}
