     9	
    10	/** Conexões, transações e criação do esquema. */
    11	public class Database implements AutoCloseable {
    12	    private static final int CONNECT_ATTEMPTS = 30;
    13	
    14	    private final HikariDataSource dataSource;
    15	
    16	    public Database(String url, String user, String password) {
    17	        HikariConfig config = new HikariConfig();
    18	        config.setJdbcUrl(url);
    19	        config.setUsername(user);
    20	        config.setPassword(password);
    21	        config.setMaximumPoolSize(10);
    22	        config.setInitializationFailTimeout(-1);
    23	        this.dataSource = new HikariDataSource(config);
    24	    }
    25	
    26	    @FunctionalInterface
    27	    public interface Work<T> {
    28	        T run(Connection connection) throws SQLException;
    29	    }
    30	
    31	    public <T> T inTransaction(Work<T> work) {
    32	        try (Connection connection = dataSource.getConnection()) {
    33	            connection.setAutoCommit(false);
    34	            try {
    35	                T result = work.run(connection);
    36	                connection.commit();
    37	                return result;
    38	            } catch (Throwable e) {
    39	                connection.rollback();
    40	                throw e;
    41	            }
    42	        } catch (SQLException e) {
    43	            throw new IllegalStateException("Erro no banco de dados: " + e.getMessage(), e);
    44	        }
    45	    }
    46	
    47	    /** Cria o que falta no banco (que começa vazio) e cadastra os quartos que ainda não existem. */
    48	    public void migrate() {
    49	        SQLException last = null;
    50	        for (int attempt = 1; attempt <= CONNECT_ATTEMPTS; attempt++) {
    51	            try {
    52	                createSchema();
    53	                return;
    54	            } catch (SQLException e) {
    55	                last = e;
    56	                try {
    57	                    Thread.sleep(1000);
    58	                } catch (InterruptedException ie) {
    59	                    Thread.currentThread().interrupt();
    60	                    break;
    61	                }
    62	            }
    63	        }
    64	        throw new IllegalStateException("Não foi possível preparar o banco de dados", last);
    65	    }
    66	
    67	    private void createSchema() throws SQLException {
    68	        try (Connection connection = dataSource.getConnection()) {
    69	            connection.setAutoCommit(false);
    70	            try (Statement st = connection.createStatement()) {
    71	                // evita corrida entre instâncias subindo ao mesmo tempo
    72	                st.execute("SELECT pg_advisory_xact_lock(7070001)");
    73	                st.execute("""
    74	                        CREATE TABLE IF NOT EXISTS rooms (
    75	                            number       INTEGER PRIMARY KEY,
    76	                            type         TEXT NOT NULL,
    77	                            capacity     INTEGER NOT NULL,
    78	                            nightly_rate NUMERIC(12,2) NOT NULL
    79	                        )""");
    80	                st.execute("""
    81	                        CREATE TABLE IF NOT EXISTS reservations (
    82	                            id          BIGSERIAL PRIMARY KEY,
    83	                            room_number INTEGER NOT NULL REFERENCES rooms(number),
    84	                            guest_name  TEXT NOT NULL,
    85	                            guest_email TEXT NOT NULL,
    86	                            guest_cpf   TEXT NOT NULL,
    87	                            check_in    DATE NOT NULL,
    88	                            check_out   DATE NOT NULL,
    89	                            guests      INTEGER NOT NULL,
    90	                            rate_plan   TEXT NOT NULL,
    91	                            nights      INTEGER NOT NULL,
    92	                            subtotal    NUMERIC(12,2) NOT NULL,
    93	                            discount    NUMERIC(12,2) NOT NULL,
    94	                            total       NUMERIC(12,2) NOT NULL,
    95	                            status      TEXT NOT NULL,
    96	                            amount_paid NUMERIC(12,2) NOT NULL,
    97	                            refund      NUMERIC(12,2)
    98	                        )""");
    99	                st.execute("CREATE INDEX IF NOT EXISTS reservations_room_dates ON reservations (room_number, check_in, check_out)");
   100	                st.execute("""
   101	                        CREATE TABLE IF NOT EXISTS messages (
   102	                            id        BIGSERIAL PRIMARY KEY,
   103	                            channel   TEXT NOT NULL,
   104	                            recipient TEXT NOT NULL,
   105	                            subject   TEXT NOT NULL,
   106	                            body      TEXT NOT NULL
   107	                        )""");
   108	                st.execute("""
   109	                        INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
   110	                            (101, 'STANDARD', 2, 249.90),
   111	                            (102, 'STANDARD', 2, 249.90),
   112	                            (201, 'DELUXE',   3, 389.90),
   113	                            (202, 'DELUXE',   3, 389.90),
   114	                            (301, 'SUITE',    4, 579.90)
   115	                        ON CONFLICT (number) DO NOTHING""");
   116	                connection.commit();
   117	            } catch (SQLException e) {
   118	                connection.rollback();
   119	                throw e;
   120	            }
   121	        }
   122	    }
   123	
   124	    @Override
   125	    public void close() {
