    21	    /** Grava uma reserva nova e devolve-a com o id gerado. */
    22	    public Reservation insert(Connection c, Reservation r) throws SQLException {
    23	        try (PreparedStatement ps = c.prepareStatement(
    24	                "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
    25	                        + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund) "
    26	                        + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
    27	                Statement.RETURN_GENERATED_KEYS)) {
    28	            ps.setInt(1, r.roomNumber());
    29	            ps.setString(2, r.guestName());
    30	            ps.setString(3, r.guestEmail());
    31	            ps.setString(4, r.guestCpf());
    32	            ps.setObject(5, r.checkIn());
    33	            ps.setObject(6, r.checkOut());
    34	            ps.setInt(7, r.guests());
    35	            ps.setString(8, r.ratePlan().name());
