    38	            ps.setBigDecimal(11, r.discount());
    39	            ps.setBigDecimal(12, r.total());
    40	            ps.setString(13, r.status().name());
    41	            ps.setBigDecimal(14, r.amountPaid());
    42	            ps.setBigDecimal(15, r.refund());
    43	            ps.executeUpdate();
    44	            try (ResultSet keys = ps.getGeneratedKeys()) {
    45	                keys.next();
    46	                long id = keys.getLong("id");
    47	                return new Reservation(id, r.roomNumber(), r.guestName(), r.guestEmail(), r.guestCpf(),
    48	                        r.checkIn(), r.checkOut(), r.guests(), r.ratePlan(), r.nights(), r.subtotal(),
    49	                        r.discount(), r.total(), r.status(), r.amountPaid(), r.refund());
    50	            }
    51	        }
    52	    }
