    74	    private Optional<Reservation> findById(Connection c, long id, String suffix) throws SQLException {
    75	        try (PreparedStatement ps = c.prepareStatement("SELECT " + COLUMNS + " FROM reservations WHERE id = ?" + suffix)) {
    76	            ps.setLong(1, id);
    77	            try (ResultSet rs = ps.executeQuery()) {
    78	                return rs.next() ? Optional.of(map(rs)) : Optional.empty();
    79	            }
