    83	    /** Há reserva não cancelada do quarto que ocupe alguma noite de [checkIn, checkOut)? */
    84	    public boolean hasOverlap(Connection c, int roomNumber, LocalDate checkIn, LocalDate checkOut) throws SQLException {
    85	        try (PreparedStatement ps = c.prepareStatement(
    86	                "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
    87	                        + "AND check_in < ? AND check_out > ? LIMIT 1")) {
    88	            ps.setInt(1, roomNumber);
    89	            ps.setObject(2, checkOut);
    90	            ps.setObject(3, checkIn);
    91	            try (ResultSet rs = ps.executeQuery()) {
    92	                return rs.next();
    93	            }
    94	        }
    95	    }
    96	
    97	    /** Reservas pagas (confirmadas, com check-in ou check-out) que ocupam o quarto na noite, por quarto. */
    98	    public List<Reservation> findPaidOnNight(Connection c, LocalDate night) throws SQLException {
    99	        return query(c, "SELECT " + COLUMNS + " FROM reservations "
   100	                + "WHERE status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT') AND check_in <= ? AND check_out > ? "
   101	                + "ORDER BY room_number, id", night, night);
   102	    }
   103	
   104	    /** Reservas que começam no intervalo [from, to) e deixaram dinheiro com a pousada. */
   105	    public List<Reservation> findRetainingMoney(Connection c, LocalDate from, LocalDate to) throws SQLException {
   106	        return query(c, "SELECT " + COLUMNS + " FROM reservations "
   107	                + "WHERE check_in >= ? AND check_in < ? AND amount_paid - COALESCE(refund, 0) > 0 "
   108	                + "ORDER BY check_in, id", from, to);
