   111	    private List<Reservation> query(Connection c, String sql, LocalDate a, LocalDate b) throws SQLException {
   112	        try (PreparedStatement ps = c.prepareStatement(sql)) {
   113	            ps.setObject(1, a);
   114	            ps.setObject(2, b);
   115	            try (ResultSet rs = ps.executeQuery()) {
   116	                List<Reservation> list = new ArrayList<>();
   117	                while (rs.next()) {
   118	                    list.add(map(rs));
   119	                }
   120	                return list;
   121	            }
   122	        }
   123	    }
