   127	                rs.getLong("id"),
   128	                rs.getInt("room_number"),
   129	                rs.getString("guest_name"),
   130	                rs.getString("guest_email"),
   131	                rs.getString("guest_cpf"),
   132	                rs.getObject("check_in", LocalDate.class),
   133	                rs.getObject("check_out", LocalDate.class),
   134	                rs.getInt("guests"),
   135	                RatePlan.valueOf(rs.getString("rate_plan")),
   136	                rs.getInt("nights"),
   137	                rs.getBigDecimal("subtotal"),
   138	                rs.getBigDecimal("discount"),
   139	                rs.getBigDecimal("total"),
   140	                ReservationStatus.valueOf(rs.getString("status")),
