 26	class DomainTest {
 27	    static final Room STANDARD = new Room(101, RoomType.STANDARD, 2, new BigDecimal("249.90"));
 28	    static final Room DELUXE = new Room(201, RoomType.DELUXE, 3, new BigDecimal("389.90"));
 29	
 30	    static LocalDate d(String s) {
 31	        return LocalDate.parse(s);
 32	    }
 33	
 34	    @Test
 35	    void highSeasonBoundaries() {
 36	        assertFalse(Pricing.isHighSeason(d("2027-12-14")));
 37	        assertTrue(Pricing.isHighSeason(d("2027-12-15")));
 38	        assertTrue(Pricing.isHighSeason(d("2028-02-29")));
 39	        assertFalse(Pricing.isHighSeason(d("2027-03-01")));
 40	        assertTrue(Pricing.isHighSeason(d("2027-07-01")));
 41	        assertTrue(Pricing.isHighSeason(d("2027-07-31")));
 42	        assertFalse(Pricing.isHighSeason(d("2027-08-01")));
 43	    }
 44	
 45	    @Test
 46	    void highSeasonExample() {
 47	        var q = Pricing.quote(STANDARD, d("2027-07-10"), d("2027-07-12"), RatePlan.STANDARD);
 48	        assertEquals(2, q.nights());
 49	        assertEquals(new BigDecimal("599.76"), q.subtotal());
 50	        assertEquals(new BigDecimal("0.00"), q.discount());
 51	        assertEquals(new BigDecimal("599.76"), q.total());
 52	    }
 53	
 54	    @Test
 55	    void stayCrossingSeasonChangeAndDiscount() {
 56	        // 14/12 normal (249.90) + 15/12 alta (299.88) = 549.78; desconto 82.467 -> 82.47
 57	        var q = Pricing.quote(STANDARD, d("2027-12-14"), d("2027-12-16"), RatePlan.NON_REFUNDABLE);
 58	        assertEquals(new BigDecimal("549.78"), q.subtotal());
 59	        assertEquals(new BigDecimal("82.47"), q.discount());
 60	        assertEquals(new BigDecimal("467.31"), q.total());
 61	    }
 62	
 63	    @Test
 64	    void roundsHalfToEven() {
 65	        assertEquals(new BigDecimal("0.12"), Money.scale(new BigDecimal("0.125")));
 66	        assertEquals(new BigDecimal("0.14"), Money.scale(new BigDecimal("0.135")));
 67	    }
 68	
 69	    @Test
 70	    void formatsMoney() {
 71	        assertEquals("R$ 1.234,56", Money.format(new BigDecimal("1234.56")));
 72	        assertEquals("R$ 0,00", Money.format(new BigDecimal("0.00")));
 73	        assertEquals("R$ 1.000.000,10", Money.format(new BigDecimal("1000000.10")));
 74	    }
