 27	/** Teste ponta a ponta contra o PostgreSQL de DB_URL, num esquema temporário. */
 28	@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
 29	class ApiTest {
 30	    static final ObjectMapper JSON = new ObjectMapper();
 31	    static final HttpClient HTTP = HttpClient.newHttpClient();
 32	    static String schema;
 33	    static Database database;
 34	    static Javalin server;
 35	    static String base;
