 37	    @BeforeAll
 38	    static void start() throws Exception {
 39	        String url = System.getenv("DB_URL");
 40	        assumeTrue(url != null && !url.isBlank(), "DB_URL não definido");
 41	        schema = "test_" + UUID.randomUUID().toString().replace("-", "");
 42	        try (Connection c = DriverManager.getConnection(url, System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
 43	             Statement st = c.createStatement()) {
 44	            st.execute("CREATE SCHEMA " + schema);
 45	        }
 46	        String scoped = url + (url.contains("?") ? "&" : "?") + "currentSchema=" + schema;
 47	        database = new Database(scoped, System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
 48	        server = Main.start(database, 0);
 49	        base = "http://localhost:" + server.port();
 50	    }
 51	
 52	    @AfterAll
 53	    static void stop() throws Exception {
 54	        if (server != null) server.stop();
 55	        if (database != null) database.close();
 56	        if (schema != null) {
 57	            try (Connection c = DriverManager.getConnection(System.getenv("DB_URL"), System.getenv("DB_USER"),
 58	                    System.getenv("DB_PASSWORD")); Statement st = c.createStatement()) {
 59	                st.execute("DROP SCHEMA " + schema + " CASCADE");
 60	            }
 61	        }
 62	    }
