 64	    record Res(int status, String body, String contentType) {
 65	        JsonNode json() throws Exception {
 66	            return JSON.readTree(body);
 67	        }
 68	    }
 69	
 70	    static Res call(String method, String path, String body) throws Exception {
 71	        var builder = HttpRequest.newBuilder(URI.create(base + path));
 72	        builder.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body));
 73	        var r = HTTP.send(builder.build(), HttpResponse.BodyHandlers.ofString());
 74	        return new Res(r.statusCode(), r.body(), r.headers().firstValue("content-type").orElse(""));
 75	    }
