174	    void cancellations() throws Exception {
175	        int before = call("GET", "/messages", null).json().size();
176	
177	        // pendente: cancela sem avisar ninguém
178	        assertEquals(201, call("POST", "/reservations", booking(201, "2027-03-10", "2027-03-12", 2, "STANDARD")).status()); // 3
179	        Res c = call("POST", "/reservations/3/cancellation", null);
180	        assertEquals("CANCELLED", c.json().get("status").asText());
181	        assertTrue(c.body().contains("\"refund\":0.00"), c.body());
182	        assertEquals(before, call("GET", "/messages", null).json().size());
183	
184	        // a noite foi liberada
185	        assertEquals(201, call("POST", "/reservations", booking(201, "2027-03-10", "2027-03-12", 2, "STANDARD")).status()); // 4
186	        call("POST", "/reservations/4/confirmation", null);
