189	        assertError(call("POST", "/reservations/4/cancellation", null), 409, "OPERATION_NOT_ALLOWED");
190	        JsonNode m = call("GET", "/messages", null).json();
191	        assertEquals(before + 3 + 2, m.size()); // confirmação (3) + cancelamento (governança e financeiro)
192	        assertEquals("Reserva cancelada - quarto 201", m.get(m.size() - 2).get("subject").asText());
193	        assertEquals("Reembolso - reserva 4", m.get(m.size() - 1).get("subject").asText());
194	
195	        // não reembolsável: só a governança é avisada
196	        assertEquals(201, call("POST", "/reservations", booking(202, "2027-03-10", "2027-03-11", 1, "NON_REFUNDABLE")).status()); // 5
197	        call("POST", "/reservations/5/confirmation", null);
198	        int mid = call("GET", "/messages", null).json().size();
199	        Res nr = call("POST", "/reservations/5/cancellation", null);
200	        assertTrue(nr.body().contains("\"refund\":0.00"), nr.body());
201	        assertEquals(mid + 1, call("GET", "/messages", null).json().size());
